practice.solution:
distances = {("Paris", "Lyon"): 465, ("Lyon", "Nice"): 470}
print(distances[("Lyon", "Nice")])

visited = set()
for cell in [(1, 2), (0, 0), (1, 2), (0, 3)]:
    visited.add(cell)
print(sorted(visited))

prices = [("tea", 4), ("cake", 6), ("bun", 4), ("jam", 3)]
for product, price in sorted(prices, key=lambda t: (t[1], t[0])):
    print(product, price)

rides = {}
for a, b in [("ana", "ben"), ("ben", "ana"), ("ana", "cy"), ("ana", "ben")]:
    pair = frozenset({a, b})
    rides[pair] = rides.get(pair, 0) + 1
print(rides[frozenset({"ben", "ana"})])
